metadata.rawInput:
{"command":"printf '%s\n' '--- zone 47 ---'; grep '^47,' data/pickup_zones.csv; printf '%s\n' '--- carriers serving zone ---'; python3 - <<'PY'
import csv
with open('data/carriers.csv') as f:
 for r in csv.DictReader(f):
  if r.get('kind','').lower() in ('trucker','truck') and r.get('active','').lower()=='true' and '47' in r.get('serves','').split(): print(r)
PY
printf '%s\n' '--- quote ---'; python3 tools/quote_air.py DUS PEK 1953 4.91 --date 2026-11-28
printf '%s\n' '--- mailbox/openapi send schema ---'; python3 - <<'PY'
import json
s=json.load(open('knowledge/openapi.json'))
for p in ['/v1/mailbox/messages','/v1/portal/rates']:
 print(p, json.dumps(s.get('paths',{}).get(p,{}),indent=2)[:6000])
PY","workdir":"/Users/joris/Downloads/start-kit2/TALOS/ultra-talos","timeout":120000}

